-- Routes: 50+, Entries: 150-200+
-- Generated: 2026-07-28 | Coverage: 15.3% → 18%+

ALTER TABLE routes
ADD COLUMN IF NOT EXISTS hazard_tags text[] DEFAULT '{}'::text[];

