UPDATE routes SET hazard_tags = COALESCE(hazard_tags, '{}'::text[]) || ARRAY['river-crossing-multiple-seasonal', 'meltwater-volume-glacier-fed', 'trail-washout-winter-storm', 'ankle-hazard-rocky-terrain', 'navigation-abandoned-road-grade', 'marine-layer-fog-transition-alpine', 'rapid-weather-front-exposure', 'wind-exposure-ridge-ascent', 'altitude-cumulative-gain-3500ft', 'snow-field-crossing-steep-slope', 'avalanche-gully-runout', 'bergschrund-upper-approach', 'crevasse-hidden-bridge-glacier', 'rime-ice-formation-exposure', 'hypothermia-wind-chill', 'cumulative-fatigue-approach-climb', 'camp-placement-wind-exposure', 'weather-window-closure-alpine', 'cloud-navigation-obscured', 'rescue-access-remote-valley'] 
WHERE LOWER(name) ILIKE '%river%crossing%multiple%seasonal, meltwater%volume%glacier%fed, trail%washout%winter%storm, ankle%hazard%rocky%terrain, navigation%abandoned%road%grade, marine%layer%fog%transition%alpine, rapid%weather%front%exposure, wind%exposure%ridge%ascent, altitude%cumulative%gain%3500ft, snow%field%crossing%steep%slope, avalanche%gully%runout, bergschrund%upper%approach, crevasse%hidden%bridge%glacier, rime%ice%formation%exposure, hypothermia%wind%chill, cumulative%fatigue%approach%climb, camp%placement%wind%exposure, weather%window%closure%alpine, cloud%navigation%obscured, rescue%access%remote%valley, equipment%stream%immersion, water%temperature%shock, route%finding%trail%fade, descent%route%error, food%supply%remote%alpine%' LIMIT 1;

UPDATE routes SET hazard_tags = COALESCE(hazard_tags, '{}'::text[]) || ARRAY['water-crossing-multiple-streams', 'snowmelt-stream-volume', 'trail-obscured-by-snow', 'snow-immersion-hazard-posthole', 'avalanche-open-slope', 'navigation-no-trail-above-treeline', 'marine-layer-fog-exposure', 'rapid-weather-transition-alpine', 'wind-exposure-exposed-ridge', 'altitude-cumulative-gain-4000ft', 'fatigue-steep-elevation-gain', 'rime-ice-tree-contact-descent', 'mosquito-swarm-alpine-zone', 'hypothermia-exposure-wind-chill', 'camp-placement-water-access-avalanche-risk', 'altitude-acclimatization-7500ft-jade-lake', 'snow-cornices-ridge-edge', 'visibility-cloud-layers-navigation', 'cumulative-dehydration-approach', 'stream-crossing-no-bridge-high-water'] 
WHERE LOWER(name) ILIKE '%water%crossing%multiple%streams, snowmelt%stream%volume, trail%obscured%by%snow, snow%immersion%hazard%posthole, avalanche%open%slope, navigation%no%trail%above%treeline, marine%layer%fog%exposure, rapid%weather%transition%alpine, wind%exposure%exposed%ridge, altitude%cumulative%gain%4000ft, fatigue%steep%elevation%gain, rime%ice%tree%contact%descent, mosquito%swarm%alpine%zone, hypothermia%exposure%wind%chill, camp%placement%water%access%avalanche%risk, altitude%acclimatization%7500ft%jade%lake, snow%cornices%ridge%edge, visibility%cloud%layers%navigation, cumulative%dehydration%approach, stream%crossing%no%bridge%high%water, crevasse%glacier%field%upper%basin, weather%window%closure%alpine, route%finding%gps%dependent, equipment%water%immersion, descending%fatigue%navigation%error%' LIMIT 1;

-- Verification query
SELECT
  COUNT(*) as total_routes,
  COUNT(CASE WHEN hazard_tags IS NOT NULL AND array_length(hazard_tags, 1) > 0 THEN 1 END) as with_hazards,
  ROUND(100.0 * COUNT(CASE WHEN hazard_tags IS NOT NULL AND array_length(hazard_tags, 1) > 0 THEN 1 END) / COUNT(*), 2) as coverage_pct
FROM routes;

